q=deque([(9,0)]); seen={(9,0)}
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  rr,cc=r+dr,c+dc
  if 0<=rr<R and 0<=cc<C and grid[rr][cc] in (8,6) and (rr,cc) not in seen:
   seen.add((rr,cc)); q.append((rr,cc))
len(seen), [(r,c) for r in range(R) for c in range(C) if grid[r][c]==8 and (r,c) not in seen]
